update known_safe_harbors set tissue_context = 'iPSCs and HEK293T (methylation comparison); neural stem cell differentiation also tested, silencing not reversed' where source_pmid = '41468306' and evidence_summary = 'In human iPSCs, CRISPR/Cas9 targeting AAVS1 to insert optogenetic/chemogenetic receptors (ChR2/hM4Di) resulted in silencing -- TRE3G BI promoter showed 95.3-98.2% methylation in iPSCs, vs. only 5.9% in HEK293T with the same construct. Hypomethylated clones also failed to express. Differentiation into neural stem cells did not reverse silencing.';
update public_safe_harbors_staging set tissue_context = 'iPSCs and HEK293T (methylation comparison); neural stem cell differentiation also tested, silencing not reversed' where source_pmid = '41468306' and evidence_summary = 'In human iPSCs, CRISPR/Cas9 targeting AAVS1 to insert optogenetic/chemogenetic receptors (ChR2/hM4Di) resulted in silencing -- TRE3G BI promoter showed 95.3-98.2% methylation in iPSCs, vs. only 5.9% in HEK293T with the same construct. Hypomethylated clones also failed to express. Differentiation into neural stem cells did not reverse silencing.';

