update known_safe_harbors set tissue_context = 'Macrophages (RNA-seq + TLR3/TLR4/TRIF signaling immunoblot)' where source_pmid = '41208113' and evidence_summary = 'Macrophages isolated from Rosa26-Cas9 mice (Cas9-FZ line, Jackson Lab #026179, the most widely used worldwide) showed no defects in any commonly tested macrophage signaling pathway (RNA-seq + TLR3/TLR4/TRIF signaling immunoblot), contradicting an earlier report of differences.';
