update known_safe_harbors set tissue_context = 'Trophoblast stem cells (hTSC), differentiated into extravillous cytotrophoblast and syncytiotrophoblast' where source_pmid = '41523105' and evidence_summary = 'Human trophoblast stem cells (hTSC, CT29 line) GFP-tagged via knock-in at AAVS1 remained proliferative and able to differentiate into extravillous cytotrophoblast and syncytiotrophoblast -- first demonstration of AAVS1 integration in this cell lineage.';
update public_safe_harbors_staging set tissue_context = 'Trophoblast stem cells (hTSC), differentiated into extravillous cytotrophoblast and syncytiotrophoblast' where source_pmid = '41523105' and evidence_summary = 'Human trophoblast stem cells (hTSC, CT29 line) GFP-tagged via knock-in at AAVS1 remained proliferative and able to differentiate into extravillous cytotrophoblast and syncytiotrophoblast -- first demonstration of AAVS1 integration in this cell lineage.';

update known_safe_harbors set tissue_context = 'Mouse embryonic stem cells (mESCs), differentiated into neurons' where source_pmid = '40036200' and evidence_summary = 'Biotin ligases (MicroID/TurboID) randomly integrated in mESCs express well in stem cells but silence completely after differentiation into neurons, regardless of promoter. The same construct targeted to the mHipp11 (H11) locus retained expression, correct localization, and activity after 8-10 days of neuronal differentiation.';
update public_safe_harbors_staging set tissue_context = 'Mouse embryonic stem cells (mESCs), differentiated into neurons' where source_pmid = '40036200' and evidence_summary = 'Biotin ligases (MicroID/TurboID) randomly integrated in mESCs express well in stem cells but silence completely after differentiation into neurons, regardless of promoter. The same construct targeted to the mHipp11 (H11) locus retained expression, correct localization, and activity after 8-10 days of neuronal differentiation.';

update known_safe_harbors set tissue_context = 'hiPSCs, differentiated into cardiomyocytes (hiPSC-CM)' where source_pmid = '39926351' and evidence_summary = 'Dox-inducible system (Tet-On 3G in hROSA26 + transgene in AAVS1) undergoes significant silencing in hiPSC-derived cardiomyocytes (hiPSC-CM). Sodium butyrate restores activity but compromises hiPSC viability. Relocating the cassette to the CLYBL locus improved promoter activity relative to AAVS1, both in hiPSC and hiPSC-CM.';
update public_safe_harbors_staging set tissue_context = 'hiPSCs, differentiated into cardiomyocytes (hiPSC-CM)' where source_pmid = '39926351' and evidence_summary = 'Dox-inducible system (Tet-On 3G in hROSA26 + transgene in AAVS1) undergoes significant silencing in hiPSC-derived cardiomyocytes (hiPSC-CM). Sodium butyrate restores activity but compromises hiPSC viability. Relocating the cassette to the CLYBL locus improved promoter activity relative to AAVS1, both in hiPSC and hiPSC-CM.';

update known_safe_harbors set tissue_context = 'Mouse embryonic stem cells (mESCs)' where source_pmid = '39777513' and evidence_summary = 'Direct comparison of 3 serine integrases (PhiC31, W-beta, Bxb1) at the Gt(ROSA)26Sor locus in mESCs -- all compatible with pluripotency and germline transmission; Bxb1 was 2-3x more efficient than the other two.';
