update known_safe_harbors set tissue_context = 'Human iPSCs' where source_pmid = '39777513' and evidence_summary = 'Bxb1 system adapted for cassette exchange at AAVS1 in hiPSCs: the CAG promoter gave consistent, stable expression; the Ef1a (EIF1A) promoter gave a very mosaic expression pattern in the same cell line -- effect depends strongly on the promoter, not just the locus.';
