update known_safe_harbors set tissue_context = 'Multiple tissues examined in vivo (mouse); heterogeneous across tissues, exact panel not itemized in evidence text' where source_pmid = '38752269' and evidence_summary = 'Direct comparison of ROSA26 vs. H11 in the same mouse (3 fluorescent reporters -- EGFP, tdTomato, mTagBFP2 -- under the CAG promoter, including a triple-transgenic model). Expression efficiency was higher at ROSA26 than H11 in most tissues examined. Substantial expression heterogeneity was observed even between cells of the same tissue.';
