update known_safe_harbors set tissue_context = 'Multiple tissues examined in vivo (mouse); heterogeneous across tissues, exact panel not itemized in evidence text' where source_pmid = '38752269' and evidence_summary = 'In the same direct comparative study with ROSA26 (3 fluorescent reporters under CAG), expression efficiency at H11 was lower than at ROSA26 in most tissues, though still functional. Substantial heterogeneity between cells of the same tissue.';
