update known_safe_harbors set tissue_context = 'Whole organism level (systemic, in vivo dog); specific tissue not itemized in evidence text' where source_pmid = '32492024' and evidence_summary = 'In transgenic dogs generated by SCNT, the hEF1a promoter was silenced by DNA methylation (expression rescued by DNMT inhibition). The CMV promoter maintained strong expression at both organism and cell level in all transgenic dogs even after 19 months. Not a named safe harbor -- random integration via SCNT -- but direct silencing data in dog, the species most relevant to this project.';
update public_safe_harbors_staging set tissue_context = 'Whole organism level (systemic, in vivo dog); specific tissue not itemized in evidence text' where source_pmid = '32492024' and evidence_summary = 'In transgenic dogs generated by SCNT, the hEF1a promoter was silenced by DNA methylation (expression rescued by DNMT inhibition). The CMV promoter maintained strong expression at both organism and cell level in all transgenic dogs even after 19 months. Not a named safe harbor -- random integration via SCNT -- but direct silencing data in dog, the species most relevant to this project.';

